draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Alexander Graham Bell invents the telephone
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';

  // Bell's head
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.fill();

  // Bell's body
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 100);
  ctx.stroke();

  // Bell's arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 30, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 30, H/2 + 70);
  ctx.stroke();

  // Telephone
  ctx.fillStyle = 'black';
  ctx.fillRect(W/2 + 50, H/2 + 70, 20, 20);
  ctx.fillRect(W/2 + 50, H/2 + 90, 20, 20);

  // Speech bubble
  ctx.beginPath();
  ctx.arc(W/2 + 90, H/2 + 60, 20 + 10*Math.sin(t), 0, 2*Math.PI);
  ctx.stroke();
  ctx.font = '14px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Mr. Watson...', W/2 + 90, H/2 + 60);

  ctx.restore();
}
